def square(x):
    """Return x squared."""
    return x ** 2


def pow(x):
    """Return x raised to the power of itself."""
    return x ** x


def outer(x, function):
    """Return a counter closure applying function to x^n."""
    count = 0

    def inner():
        """Apply function to x raised to the call count."""
        nonlocal count
        count += 1
        return function(x ** count)

    return inner
